CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user', balance BIGINT NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, available_rc BIGINT NOT NULL DEFAULT 0, pending_rc BIGINT NOT NULL DEFAULT 0, legacy_balance_kobo BIGINT NOT NULL DEFAULT 0);
CREATE TABLE advertiser_profiles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE REFERENCES users(id), business_name TEXT NOT NULL, website TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending_review', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE platform_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_by BIGINT REFERENCES users(id), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE app_migrations (name TEXT PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ledger_entries (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, reference TEXT NOT NULL UNIQUE, user_id BIGINT REFERENCES users(id), entry_type TEXT NOT NULL, amount_rc BIGINT NOT NULL DEFAULT 0, amount_kobo BIGINT NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'posted', entity_type TEXT NOT NULL DEFAULT '', entity_id BIGINT, idempotency_key TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', actor_user_id BIGINT REFERENCES users(id), metadata TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_user_id BIGINT REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id BIGINT, details TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), type TEXT NOT NULL, title TEXT NOT NULL, message TEXT NOT NULL, entity_type TEXT NOT NULL DEFAULT '', entity_id BIGINT, read_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE campaigns (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT NOT NULL, advertiser TEXT NOT NULL, description TEXT DEFAULT '', video_url TEXT NOT NULL, destination_url TEXT DEFAULT '', reward BIGINT NOT NULL DEFAULT 10, duration_seconds BIGINT NOT NULL DEFAULT 5, budget BIGINT NOT NULL DEFAULT 0, active BIGINT NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, status TEXT NOT NULL DEFAULT 'active', advertiser_user_id BIGINT REFERENCES users(id), objective TEXT NOT NULL DEFAULT 'video_visibility', qualifying_rules TEXT NOT NULL DEFAULT 'Watch for at least 90% of the advertised video duration. Reward is pending until administrator review.', approval_status TEXT NOT NULL DEFAULT 'pending_review', funding_status TEXT NOT NULL DEFAULT 'unfunded', advertiser_budget_kobo BIGINT NOT NULL DEFAULT 0, funded_kobo BIGINT NOT NULL DEFAULT 0, reward_budget_rc BIGINT NOT NULL DEFAULT 0, reward_allocation_bps BIGINT NOT NULL DEFAULT 5000, platform_allocation_bps BIGINT NOT NULL DEFAULT 0, operating_reserve_bps BIGINT NOT NULL DEFAULT 0, viewer_reward_allocation_kobo BIGINT NOT NULL DEFAULT 0, platform_allocation_kobo BIGINT NOT NULL DEFAULT 0, operating_reserve_kobo BIGINT NOT NULL DEFAULT 0, reward_rate_rc BIGINT NOT NULL DEFAULT 1000, reward_rate_kobo BIGINT NOT NULL DEFAULT 10000, target_completions BIGINT NOT NULL DEFAULT 0, website_engagement_seconds BIGINT NOT NULL DEFAULT 30, action_type TEXT NOT NULL DEFAULT 'none', action_reward_rc BIGINT NOT NULL DEFAULT 0, max_action_rewards BIGINT NOT NULL DEFAULT 0, review_reason TEXT NOT NULL DEFAULT '', reviewed_by BIGINT REFERENCES users(id), reviewed_at TEXT, expires_at TEXT);
CREATE TABLE views (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), campaign_id BIGINT NOT NULL REFERENCES campaigns(id), reward BIGINT NOT NULL, watched_seconds BIGINT NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'completed', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, attempt_reference TEXT NOT NULL DEFAULT '', rejection_reason TEXT NOT NULL DEFAULT '', reviewed_by BIGINT REFERENCES users(id), reviewed_at TEXT, UNIQUE(user_id,campaign_id));
CREATE TABLE withdrawals (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), amount BIGINT NOT NULL, method TEXT NOT NULL, account_details TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, request_reference TEXT NOT NULL DEFAULT '', amount_rc BIGINT NOT NULL DEFAULT 0, gross_kobo BIGINT NOT NULL DEFAULT 0, fee_kobo BIGINT NOT NULL DEFAULT 0, payout_kobo BIGINT NOT NULL DEFAULT 0, bank_name TEXT NOT NULL DEFAULT '', destination_encrypted TEXT NOT NULL DEFAULT '', account_last4 TEXT NOT NULL DEFAULT '', account_name TEXT NOT NULL DEFAULT '', rate_rc BIGINT NOT NULL DEFAULT 0, rate_kobo BIGINT NOT NULL DEFAULT 0, idempotency_key TEXT NOT NULL DEFAULT '', rejection_reason TEXT NOT NULL DEFAULT '', payout_reference TEXT NOT NULL DEFAULT '', payout_evidence TEXT NOT NULL DEFAULT '', reviewed_by BIGINT REFERENCES users(id), reviewed_at TEXT, processing_at TEXT, paid_at TEXT, paid_by BIGINT REFERENCES users(id));
CREATE TABLE campaign_fundings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, campaign_id BIGINT NOT NULL REFERENCES campaigns(id), amount_kobo BIGINT NOT NULL, status TEXT NOT NULL DEFAULT 'pending_review', provider TEXT NOT NULL DEFAULT 'manual', advertiser_reference TEXT NOT NULL DEFAULT '', reconciliation_reference TEXT NOT NULL DEFAULT '', submitted_by BIGINT NOT NULL REFERENCES users(id), confirmed_by BIGINT REFERENCES users(id), verification_note TEXT NOT NULL DEFAULT '', confirmed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(provider,reconciliation_reference));
CREATE TABLE support_tickets (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), category TEXT NOT NULL, subject TEXT NOT NULL, message TEXT NOT NULL, entity_type TEXT NOT NULL DEFAULT '', entity_id BIGINT, status TEXT NOT NULL DEFAULT 'open', admin_response TEXT NOT NULL DEFAULT '', resolved_by BIGINT REFERENCES users(id), resolved_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE watch_sessions (token TEXT PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), campaign_id BIGINT NOT NULL REFERENCES campaigns(id), started_at BIGINT NOT NULL, required_seconds BIGINT NOT NULL, reserved_reward BIGINT NOT NULL);
CREATE TABLE campaign_tracking_sessions (id TEXT PRIMARY KEY, campaign_id BIGINT NOT NULL REFERENCES campaigns(id), user_id BIGINT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, destination_url TEXT NOT NULL, clicked_at BIGINT NOT NULL, landed_at BIGINT, visible_seconds BIGINT NOT NULL DEFAULT 0, expires_at BIGINT NOT NULL, reserved_reward BIGINT NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE campaign_tracking_events (event_id TEXT PRIMARY KEY, campaign_id BIGINT NOT NULL REFERENCES campaigns(id), user_id BIGINT NOT NULL REFERENCES users(id), session_id TEXT REFERENCES campaign_tracking_sessions(id), event_type TEXT NOT NULL, details TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE action_reward_claims (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, campaign_id BIGINT NOT NULL REFERENCES campaigns(id), user_id BIGINT NOT NULL REFERENCES users(id), tracking_session_id TEXT NOT NULL UNIQUE REFERENCES campaign_tracking_sessions(id), event_id TEXT NOT NULL DEFAULT '', action_type TEXT NOT NULL, reward_rc BIGINT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', review_reason TEXT NOT NULL DEFAULT '', reviewed_by BIGINT, reviewed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE session_store (sid TEXT PRIMARY KEY, sess JSON NOT NULL, expire TIMESTAMPTZ NOT NULL);
CREATE INDEX "IDX_session_store_expire" ON session_store(expire);
CREATE TABLE rate_limit_hits (bucket TEXT NOT NULL, hit_at BIGINT NOT NULL);
CREATE TABLE password_reset_tokens (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, expires_at BIGINT NOT NULL, used_at BIGINT, created_at BIGINT NOT NULL);
CREATE INDEX idx_tracking_campaign_event ON campaign_tracking_events(campaign_id,event_type,created_at);
CREATE UNIQUE INDEX idx_action_claim_once ON action_reward_claims(campaign_id,user_id,action_type);
CREATE UNIQUE INDEX idx_action_claim_event ON action_reward_claims(event_id) WHERE event_id <> '';
CREATE INDEX idx_action_claim_status ON action_reward_claims(status,created_at);
CREATE INDEX idx_password_reset_user ON password_reset_tokens(user_id,expires_at);
CREATE INDEX idx_rate_limit_hits ON rate_limit_hits(bucket,hit_at);
CREATE UNIQUE INDEX idx_withdrawal_reference ON withdrawals(request_reference) WHERE request_reference <> '';
CREATE UNIQUE INDEX idx_withdrawal_idempotency ON withdrawals(user_id,idempotency_key) WHERE idempotency_key <> '';
CREATE UNIQUE INDEX idx_view_attempt_reference ON views(attempt_reference) WHERE attempt_reference <> '';
CREATE INDEX idx_ledger_user_created ON ledger_entries(user_id,created_at DESC);
CREATE INDEX idx_notifications_user_created ON notifications(user_id,created_at DESC);
CREATE INDEX idx_campaign_funding_status ON campaign_fundings(status,created_at);
CREATE UNIQUE INDEX idx_funding_submitted_reference ON campaign_fundings(submitted_by,advertiser_reference) WHERE advertiser_reference <> '';
